import { create } from 'zustand';
import { KDSOrder, KitchenStage } from '../types/kds';
import { calculateETA } from '../utils/etaUtils';
import { KDSRole, canDelayOrder, canCancelOrder, canOverrideStage } from '../utils/kdsAccess';

interface PendingAction {
    id: string;
    type: string;
    payload: any;
    timestamp: string;
}

interface KDSState {
    orders: Record<string, KDSOrder>;
    externalOrderMap: Record<string, string>; // external_order_id -> order.id
    isOnline: boolean;
    pendingActions: PendingAction[];

    addOrUpdateOrder: (order: KDSOrder) => void;
    removeOrder: (orderId: string) => void;
    updateOrderStage: (orderId: string, stage: KitchenStage) => void;
    acceptOrder: (orderId: string) => void;
    advanceStage: (orderId: string) => void;
    markDelayed: (orderId: string, reason?: string) => void;
    delayOrder: (orderId: string, additionalMinutes: number, role: KDSRole, reason?: string) => void;
    cancelOrder: (orderId: string, role: KDSRole) => void;
    overrideStage: (orderId: string, stage: KitchenStage, role: KDSRole) => void;
    incrementPrepTime: (orderId: string, minutes?: number) => void;
    sendCustomerMessage: (orderId: string, channel: 'SMS' | 'EMAIL' | 'BOTH', message: string) => void;
    setOnlineStatus: (status: boolean) => void;
    queueAction: (type: string, payload: any) => void;
    replayQueuedActions: () => void;
}

export const useKDSStore = create<KDSState>((set, get) => ({
    orders: {},
    externalOrderMap: {},
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    pendingActions: [],

    addOrUpdateOrder: (order) =>
        set((state) => {
            const existing = state.orders[order.id];

            // Idempotency check: Ignore older or duplicate updates
            if (existing && new Date(order.updatedAt) <= new Date(existing.updatedAt)) {
                return state;
            }

            const newExternalMap = { ...state.externalOrderMap };
            if (order.external_order_id) {
                newExternalMap[order.external_order_id] = order.id;
            }

            return {
                orders: {
                    ...state.orders,
                    [order.id]: order,
                },
                externalOrderMap: newExternalMap,
            };
        }),

    removeOrder: (orderId) =>
        set((state) => {
            const order = state.orders[orderId];
            const newOrders = { ...state.orders };
            const newExternalMap = { ...state.externalOrderMap };

            if (order?.external_order_id) {
                delete newExternalMap[order.external_order_id];
            }
            delete newOrders[orderId];

            return {
                orders: newOrders,
                externalOrderMap: newExternalMap
            };
        }),

    queueAction: (type, payload) => {
        set((state) => ({
            pendingActions: [
                ...state.pendingActions,
                {
                    id: crypto.randomUUID(),
                    type,
                    payload,
                    timestamp: new Date().toISOString()
                }
            ]
        }));
    },

    updateOrderStage: (orderId, stage) => {
        const { isOnline, queueAction } = get();

        // Immediate local update (Optimistic UI)
        set((state: KDSState) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const now = new Date();
            let updates: Partial<KDSOrder> = {
                stage,
                stageStartedAt: now.toISOString(),
                isPendingSync: !isOnline,
            };

            // Workflow automation: If starting PREPARATION, ensure prepTime and ETA are set
            if (stage === 'PREPARATION') {
                const prepTime = order.prepTimeMinutes || 10;
                const createdAt = new Date(order.createdAt);
                createdAt.setMinutes(createdAt.getMinutes() + prepTime);

                updates = {
                    ...updates,
                    prepTimeMinutes: prepTime,
                    estimatedReadyTime: createdAt.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    })
                };
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        ...updates,
                    },
                },
            };
        });

        if (!isOnline) {
            queueAction('UPDATE_STAGE', { orderId, stage });
        }
    },

    acceptOrder: (orderId: string) => {
        const { isOnline, queueAction } = get();

        set((state: KDSState) => {
            const order = state.orders[orderId];
            if (!order || order.stage !== 'ACCEPTED') return state;

            const now = new Date().toISOString();
            const prepTime = order.prepTimeMinutes || 10;
            const eta = calculateETA(order.createdAt, prepTime);

            const prevStageEntry = {
                stage: order.stage,
                startedAt: order.stageStartedAt || order.createdAt,
                completedAt: now,
            };

            const stageHistory = [...(order.stageHistory || []), prevStageEntry];

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        stage: 'PREPARATION',
                        stageStartedAt: now,
                        prepTimeMinutes: prepTime,
                        estimatedReadyTime: eta,
                        stageHistory,
                        isPendingSync: !isOnline,
                    },
                },
            };
        });

        if (!isOnline) {
            queueAction('ACCEPT_ORDER', { orderId });
        }
    },

    advanceStage: (orderId: string) => {
        const { isOnline, queueAction } = get();
        const currentOrder = get().orders[orderId];
        if (!currentOrder) return;

        // If already READY, "advancing" means completing/removing the order
        if (currentOrder.stage === 'READY') {
            get().removeOrder(orderId);
            if (!isOnline) queueAction('REMOVE_ORDER', { orderId });
            return;
        }

        set((state: KDSState) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const stages: KitchenStage[] = ['ACCEPTED', 'PREPARATION', 'CUTTING', 'READY'];
            const currentIndex = stages.indexOf(order.stage);
            const nextStage = stages[currentIndex + 1];

            if (!nextStage) return state;

            const now = new Date().toISOString();
            const prevStageEntry = {
                stage: order.stage,
                startedAt: order.stageStartedAt || order.createdAt,
                completedAt: now,
            };

            const stageHistory = [...(order.stageHistory || []), prevStageEntry];

            let updates: Partial<KDSOrder> = {
                stage: nextStage,
                stageStartedAt: now,
                stageHistory,
                isPendingSync: !isOnline,
            };

            // Workflow automation: If starting PREPARATION, ensure prepTime and ETA are set
            if (nextStage === 'PREPARATION') {
                const prepTime = order.prepTimeMinutes || 10;
                const createdAt = new Date(order.createdAt);
                createdAt.setMinutes(createdAt.getMinutes() + prepTime);

                updates = {
                    ...updates,
                    prepTimeMinutes: prepTime,
                    estimatedReadyTime: createdAt.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    })
                };
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        ...updates,
                    },
                },
            };
        });

        if (!isOnline) {
            queueAction('ADVANCE_STAGE', { orderId });
        }
    },

    markDelayed: (orderId, reason) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        isDelayed: true,
                        delayReason: reason,
                    },
                },
            };
        }),

    delayOrder: (orderId: string, additionalMinutes: number, role: KDSRole, reason?: string) => {
        if (!canDelayOrder(role)) {
            console.warn(`Role ${role} is not authorized to delay orders`);
            return;
        }
        const { isOnline, queueAction } = get();

        // Immediate local update (Optimistic UI)
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const now = new Date().toISOString();

            // Recalculate ETA using the new total prep time from original createdAt
            const newTotalPrepTime = (order.prepTimeMinutes || 0) + additionalMinutes;
            const newETA = calculateETA(order.createdAt, newTotalPrepTime);

            const delayEntry = {
                minutes: additionalMinutes,
                reason,
                timestamp: now,
            };

            const delayLog = [...(order.delayLog || []), delayEntry];

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        prepTimeMinutes: newTotalPrepTime,
                        estimatedReadyTime: newETA,
                        isDelayed: true,
                        delayReason: reason || order.delayReason,
                        delayLog,
                        isPendingSync: !isOnline,
                    },
                },
            };
        });

        if (!isOnline) {
            queueAction('DELAY_ORDER', { orderId, additionalMinutes, reason });
        }

        // Delay Sync for Uber
        const order = get().orders[orderId];
        if (order?.order_source === 'UBER_DIRECT') {
            // TODO: sync updated ETA to Uber Direct API
        }
    },

    cancelOrder: (orderId, role) => {
        if (!canCancelOrder(role)) {
            console.warn(`Role ${role} is not authorized to cancel orders`);
            return;
        }
        const { isOnline, queueAction } = get();

        set((state) => {
            const newOrders = { ...state.orders };
            delete newOrders[orderId];
            return { orders: newOrders };
        });

        if (!isOnline) {
            queueAction('CANCEL_ORDER', { orderId });
        }
    },

    overrideStage: (orderId, stage, role) => {
        if (!canOverrideStage(role)) {
            console.warn(`Role ${role} is not authorized to override stages`);
            return;
        }
        get().updateOrderStage(orderId, stage);
    },

    incrementPrepTime: (orderId, minutes = 5) => {
        const { isOnline, queueAction } = get();

        set((state) => {
            const order = state.orders[orderId];
            if (!order || order.stage === 'READY') return state;

            const newPrepTime = Math.max(1, (order.prepTimeMinutes || 0) + minutes);
            const newETA = calculateETA(order.createdAt, newPrepTime);

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        prepTimeMinutes: newPrepTime,
                        estimatedReadyTime: newETA,
                        isPendingSync: !isOnline,
                    },
                },
            };
        });

        if (!isOnline) {
            queueAction('INCREMENT_PREP_TIME', { orderId, minutes });
        }
    },

    sendCustomerMessage: (orderId, channel, message) => {
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const logEntry = {
                channel,
                message,
                sentAt: new Date().toISOString(),
                sentBy: 'current_user_id', // Placeholder
            };

            const notificationsLog = [...(order.notificationsLog || []), logEntry];

            // TODO: emit customer_notifications event
            // TODO: integrate SMS service
            // TODO: integrate Email service

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        notificationsLog,
                    },
                },
            };
        });
    },

    setOnlineStatus: (status: boolean) => {
        const wasOffline = !get().isOnline;
        set({ isOnline: status });

        if (status && wasOffline) {
            get().replayQueuedActions();
        }
    },

    replayQueuedActions: () => {
        const { pendingActions } = get();
        if (pendingActions.length === 0) return;

        console.log(`📡 Reconnecting: Replaying ${pendingActions.length} queued actions...`);

        // Placeholder for batch sync
        pendingActions.forEach(action => {
            console.log(`Syncing action: ${action.type}`, action.payload);
            // TODO: sync to backend
        });

        set({ pendingActions: [] });

        // Update all orders to mark as synced
        set((state) => {
            const updatedOrders = { ...state.orders };
            Object.keys(updatedOrders).forEach(id => {
                const order = updatedOrders[id];
                if (order) {
                    updatedOrders[id] = { ...order, isPendingSync: false };
                }
            });
            return { orders: updatedOrders };
        });
    },
}));
